{"files":[{"path":"index.html","old_sha256":"76cda301f0d1bf073c55adb7fc2ed12e84814a4c889266cd8a8bfce658ba446c","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Voxel Sandbox</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<header>
  <h1>Voxel Sandbox</h1>
  <div class="hud">
    <div id="world">world 8x8</div>
    <div id="position">1,1,1</div>
    <div id="facing">east</div>
    <div id="selected">none</div>
    <div id="status">ready</div>
  </div>
  <div class="controls">
    <button id="turn-left">Turn Left</button>
    <button id="turn-right">Turn Right</button>
    <button id="break">Break</button>
    <select id="hotbar"><option value="dirt" selected>dirt</option><option value="stone">stone</option></select>
    <button id="place">Place</button>
  </div>
</header>
<main>
  <div id="scene"></div>
</main>
<script src="world.js"></script>
<script src="rules.js"></script>
<script src="app.js"></script>
</body>
</html>
"},{"path":"world.js","old_sha256":"11bdbfe114b1e0a9152c0c49688830fa3c09ce327532dc722cf6ee51c9ad16a4","content":"const World = {
  size: 8,
  blocks: {},
  player: { x: 1, y: 1, z: 1, facing: 'east' },
  dirs: { east: [1, 0], south: [0, 1], west: [-1, 0], north: [0, -1] },
  key(x, y, z) { return x + ',' + y + ',' + z; },
  inBounds(x, y, z) { return x >= 0 && x < this.size && z >= 0 && z < this.size && y >= 0 && y <= 8; },
  get(x, y, z) { return this.blocks[this.key(x, y, z)] || null; },
  set(x, y, z, material) { this.blocks[this.key(x, y, z)] = { x, y, z, material }; },
  remove(x, y, z) { delete this.blocks[this.key(x, y, z)]; },
  init() {
    this.blocks = {};
    for (let x = 0; x < this.size; x++)
      for (let z = 0; z < this.size; z++)
        this.set(x, 0, z, 'ground');
    this.set(2, 1, 1, 'dirt');
    this.set(4, 1, 1, 'dirt');
    this.set(6, 1, 1, 'dirt');
    this.player = { x: 1, y: 1, z: 1, facing: 'east' };
  },
  turn(dir) {
    const order = ['north', 'east', 'south', 'west'];
    let i = order.indexOf(this.player.facing);
    i = (i + (dir === 'left' ? -1 : 1) + 4) % 4;
    this.player.facing = order[i];
  },
  move(dx, dz) {
    const nx = this.player.x + dx, nz = this.player.z + dz;
    if (!this.inBounds(nx, this.player.y, nz)) return false;
    this.player.x = nx; this.player.z = nz;
    return true;
  },
  target() {
    const d = this.dirs[this.player.facing];
    return { x: this.player.x + d[0], y: this.player.y, z: this.player.z + d[1] };
  },
  breakBlock(x, y, z) {
    const b = this.get(x, y, z);
    if (!b || b.material === 'ground') return false;
    if (!Rules.canInteract(this.player, x, y, z)) return false;
    this.remove(x, y, z);
    return true;
  },
  placeBlock(x, y, z, material) {
    if (!this.inBounds(x, y, z)) return false;
    if (this.get(x, y, z)) return false;
    if (x === this.player.x && z === this.player.z && y === this.player.y) return false;
    if (!Rules.canInteract(this.player, x, y, z)) return false;
    this.set(x, y, z, material);
    return true;
  }
};
"},{"path":"app.js","old_sha256":"9ba6978ad43617465d529c6b0c103c7aec45c3da2c0daf173482e7bd93242920","content":"const scene = document.getElementById('scene');
const el = id => document.getElementById(id);
const TILE = 48, H = 24, OX = 320, OY = 240;
let selected = null;

function project(x, y, z) {
  return { left: OX + (x - z) * (TILE / 2), top: OY + (x + z) * (H / 2) - y * TILE };
}

function render() {
  scene.innerHTML = '';
  const items = [];
  for (const k in World.blocks) {
    const b = World.blocks[k];
    items.push({ b, depth: b.x + b.z + b.y * 0.001 });
  }
  items.push({ b: { x: World.player.x, y: World.player.y, z: World.player.z, material: 'player' }, depth: World.player.x + World.player.z + 0.5 });
  items.sort((a, b) => a.depth - b.depth);
  for (const it of items) {
    const b = it.b;
    const p = project(b.x, b.y, b.z);
    const div = document.createElement('div');
    div.className = 'cube' + (b.material === 'ground' ? ' ground' : '') + (b.material === 'player' ? ' player' : '');
    if (selected && b.material !== 'player' && b.x === selected.x && b.y === selected.y && b.z === selected.z) div.className += ' selected';
    div.style.left = p.left + 'px';
    div.style.top = p.top + 'px';
    div.style.zIndex = Math.round(b.x + b.z + b.y * 10);
    if (b.material !== 'player') div.setAttribute('data-block', b.x + ',' + b.y + ',' + b.z);
    div.innerHTML = '<div class="top"></div><div class="left"></div><div class="right"></div><div class="label">' + b.material + '</div>';
    scene.appendChild(div);
  }
  updateHUD();
}

function updateHUD() {
  el('world').textContent = 'world ' + World.size + 'x' + World.size;
  el('position').textContent = World.player.x + ',' + World.player.y + ',' + World.player.z;
  el('facing').textContent = World.player.facing;
  el('selected').textContent = selected ? selected.x + ',' + selected.y + ',' + selected.z : 'none';
}

function status(msg) { el('status').textContent = msg; }

function parseCoord(str) {
  const parts = str.split(',').map(Number);
  if (parts.length !== 3 || parts.some(n => !Number.isInteger(n))) return null;
  return { x: parts[0], y: parts[1], z: parts[2] };
}

function onCubeClick(e) {
  const c = e.target.closest('.cube');
  if (!c || c.classList.contains('player')) return;
  const coord = parseCoord(c.getAttribute('data-block'));
  if (!coord || !World.inBounds(coord.x, coord.y, coord.z)) { status('invalid coordinate'); return; }
  const b = World.get(coord.x, coord.y, coord.z);
  if (!b) { status('no block at ' + coord.x + ',' + coord.y + ',' + coord.z); return; }
  if (b.material === 'ground') { status('ground cannot be selected'); return; }
  if (!Rules.canInteract(World.player, coord.x, coord.y, coord.z)) { status('out of range'); return; }
  selected = { x: coord.x, y: coord.y, z: coord.z };
  status('selected ' + coord.x + ',' + coord.y + ',' + coord.z);
  render();
}

function onBreak() {
  if (!selected) { status('nothing selected'); return; }
  const b = World.get(selected.x, selected.y, selected.z);
  if (!b) { status('selected block gone'); selected = null; render(); return; }
  if (b.material === 'ground') { status('ground cannot be removed'); selected = null; render(); return; }
  if (!Rules.canInteract(World.player, selected.x, selected.y, selected.z)) { status('out of range'); selected = null; render(); return; }
  World.breakBlock(selected.x, selected.y, selected.z);
  status('broke ' + b.material + ' at ' + selected.x + ',' + selected.y + ',' + selected.z);
  selected = null;
  render();
}

function onPlace() {
  const mat = el('hotbar').value;
  const t = World.target();
  if (!World.placeBlock(t.x, 1, t.z, mat)) { status('cannot place ' + mat + ' at ' + t.x + ',1,' + t.z); return; }
  status('placed ' + mat + ' at ' + t.x + ',1,' + t.z);
  render();
}

function canStand(x, z) {
  if (!World.inBounds(x, 1, z)) return false;
  if (World.get(x, 1, z)) return false;
  if (World.get(x, 2, z)) return false;
  return true;
}

function movePlayer(dx, dz) {
  const nx = World.player.x + dx, nz = World.player.z + dz;
  if (!canStand(nx, nz)) { status('blocked at ' + nx + ',' + nz); return; }
  World.player.x = nx; World.player.z = nz;
  status('moved to ' + nx + ',' + World.player.y + ',' + nz);
  render();
}

function onKey(e) {
  const d = World.dirs[World.player.facing];
  const k = e.key.toLowerCase();
  if (k === 'w') movePlayer(d[0], d[1]);
  else if (k === 's') movePlayer(-d[0], -d[1]);
  else if (k === 'a') movePlayer(-d[1], d[0]);
  else if (k === 'd') movePlayer(d[1], -d[0]);
}

el('turn-left').addEventListener('click', () => { World.turn('left'); status('facing ' + World.player.facing); render(); });
el('turn-right').addEventListener('click', () => { World.turn('right'); status('facing ' + World.player.facing); render(); });
el('break').addEventListener('click', onBreak);
el('place').addEventListener('click', onPlace);
scene.addEventListener('click', onCubeClick);
document.addEventListener('keydown', onKey);

World.init();
render();
"},{"path":"style.css","old_sha256":"f2e7998a77d3a462b15d5e51e5fc825f1ab41970b3868465d94467c01888c58c","content":"*{box-sizing:border-box}
body{margin:0;font-family:system-ui,sans-serif;background:#1c1e26;color:#e8e8f0}
header{padding:12px 16px;border-bottom:1px solid #333}
h1{margin:0 0 8px;font-size:18px}
.hud{display:flex;gap:16px;flex-wrap:wrap;font-size:13px;margin-bottom:10px}
.hud div{background:#262a36;padding:4px 10px;border-radius:6px}
.controls{display:flex;gap:8px;align-items:center}
button{background:#3a6df0;color:#fff;border:0;padding:8px 14px;border-radius:6px;cursor:pointer;font-size:13px}
button:hover{background:#4a7df5}
select{background:#262a36;color:#e8e8f0;border:1px solid #444;padding:8px 10px;border-radius:6px;font-size:13px}
#scene{position:relative;width:640px;height:560px;margin:24px auto;overflow:hidden}
.cube{position:absolute;width:48px;height:48px;cursor:pointer}
.cube .top{position:absolute;inset:0;background:#8a5a2b;transform:skewX(-30deg) scaleY(.5);transform-origin:50% 100%}
.cube .left{position:absolute;left:0;top:24px;width:24px;height:24px;background:#5e3d1c;transform:skewY(30deg);transform-origin:0 0}
.cube .right{position:absolute;right:0;top:24px;width:24px;height:24px;background:#74491f;transform:skewY(-30deg);transform-origin:100% 0}
.cube .label{position:absolute;left:0;top:26px;width:48px;text-align:center;font-size:10px;color:#fff;text-shadow:0 1px 2px #000;pointer-events:none}
.cube.ground .top{background:#3f7d3a}
.cube.ground .left{background:#2c5a29}
.cube.ground .right{background:#356b30}
.cube.stone .top{background:#8a8a92}
.cube.stone .left{background:#5f5f66}
.cube.stone .right{background:#70707a}
.cube.player .top{background:#3a6df0}
.cube.player .left{background:#2749a8}
.cube.player .right{background:#2f57c4}
.cube.player .label{font-weight:700}
.cube.selected .top{outline:2px solid #ffd54a;outline-offset:-2px}
.cube.selected .left{outline:2px solid #ffd54a;outline-offset:-2px}
.cube.selected .right{outline:2px solid #ffd54a;outline-offset:-2px}
.cube:hover{filter:brightness(1.15)}
